import numpy as np
import math

def private_count(data, epsilon, rng):
    count = sum(data)
    noise = rng.laplace(loc=0.0, scale=1.0 / epsilon)
    return float(count + noise)

import numpy as np
import math

def private_histogram(data, epsilon, rng):
    counts = {"A": 0, "B": 0, "C": 0}
    for label in data:
        if label in counts:
            counts[label] += 1

    scale = 1.0 / epsilon
    noisy_counts = {}
    for key in ["A", "B", "C"]:
        noise = rng.laplace(loc=0.0, scale=scale)
        noisy_counts[key] = float(counts[key] + noise)

    return noisy_counts

import numpy as np
import math

def randomized_response(data, epsilon, rng):
    true_bit = data[0]
    prob_truth = math.exp(epsilon) / (1 + math.exp(epsilon))
    if rng.random() < prob_truth:
        return true_bit
    else:
        return 1 - true_bit
